/**
 * 16 character avatars for the AdkClaw cohort fleet.
 *
 * Categories: 8 boys, 8 girls (with mixed looks — some hijab, some not).
 * Each character has a personality tag (studious / cool / friendly / creative).
 *
 * Rendering: painterly portraits in `public/avatars/<id>.png`, generated by
 * `scripts/generate-avatars.mjs` via Imagen 3 on Vertex AI.
 */

import type { AvatarPreset } from './types';

export type AvatarCategory = 'boys' | 'girls';
export type AvatarPersonality = 'studious' | 'cool' | 'friendly' | 'creative';

export interface AvatarCharacter {
  id: AvatarPreset;
  /** No longer displayed — kept for backwards compatibility with existing data. */
  name: string;
  category: AvatarCategory;
  personality: AvatarPersonality;
  /** Accent color for the ring + glow cue */
  accent: string;
  /** Soft-glow halo color (rgba) */
  glow: string;
}

