/**
 * Backwards-compat alias for code that imported AVATAR_PALETTES.
 */
export const AVATAR_PALETTES = AVATAR_CHARACTERS;

/**
 * Path to a character's painterly portrait. Generated by
 * scripts/generate-avatars.mjs (Imagen 3 on Vertex AI).
 */
export function avatarUrl(character: AvatarCharacter): string {
  return `/avatars/${character.id}.png`;
}
